// One fixed, non-interactive canvas persists across tabs and scroll positions.
(()=>{const canvas=document.getElementById('site-grid'),ctx=canvas.getContext('2d');const phrases=['PASS THE MIC.','CHANGE WHO DECIDES.','MAKE ROOM FOR EVERY VOICE.','NO WOMAN IN THE ROOM?','PAUSE THE DECISION.'];let timer,visible=true;
function draw(){if(!visible)return;const w=innerWidth,h=innerHeight,d=Math.min(devicePixelRatio||1,2),style=getComputedStyle(document.documentElement),step=Number(style.getPropertyValue('--site-gridSpacing'))||(w<600?12:15),opacity=Number(style.getPropertyValue('--site-gridOpacity'))||0,color=style.getPropertyValue('--site-gridColor').trim()||'#000000';canvas.width=w*d;canvas.height=h*d;ctx.scale(d,d);ctx.clearRect(0,0,w,h);ctx.strokeStyle='rgba(0,0,0,'+(Number(style.getPropertyValue('--site-gridLineOpacity'))||0)+')';ctx.lineWidth=.5;ctx.beginPath();for(let x=0;x<w;x+=step){ctx.moveTo(x,0);ctx.lineTo(x,h)}for(let y=0;y<h;y+=step){ctx.moveTo(0,y);ctx.lineTo(w,y)}ctx.stroke();ctx.font=`500 ${step*.76}px monospace`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle=color;ctx.globalAlpha=opacity;const epoch=Math.floor(Date.now()/2000);for(let row=0,y=step/2;y<h;y+=step,row++){const phrase=phrases[(row*7+epoch)%phrases.length]+' ';for(let col=0,x=step/2;x<w;x+=step,col++)ctx.fillText(phrase[(col+row*3)%phrase.length],x,y)}}
document.addEventListener('site-style-change',draw);function schedule(){clearInterval(timer);visible=!document.hidden;draw();if(visible)timer=setInterval(draw,2000)}addEventListener('resize',draw);document.addEventListener('visibilitychange',schedule);schedule();addEventListener('pagehide',()=>clearInterval(timer));})();
